import 'package:flutter/cupertino.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../domain/useCase/refresh_token_use_case.dart';import '../../../../../../Config/Routes/route_name.dart';import '../../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../../Core/Storage/Local/local_storage_service.dart';import '../../../../../../Core/Utils/Widget/custom_scaffold_messenger.dart';import '../../../../../../main.dart';import '../../../../../Global/Authentication/data/Models/user_data_model.dart';import '../../data/models/update_password.dart';import '../../domain/useCase/get_user_data_use_case.dart';import '../../domain/useCase/update_password_use_case.dart';import '../../domain/useCase/update_user_use_case.dart';import '../../data/models/update_user.dart';part 'user_state.dart';class UserCubit extends Cubit<UserClassState> {  UserCubit(this.updateUserUseCase, this.updatePasswordUseCase,      this.getUserDataUseCase, this.refreshTokenUseCase)      : super(UserClassState(          userDataModel: UserDataModel(            id: 0,            name: "User",            email: "User@.com",            emailVerifiedAt: false,            phone: "",            photo: "default.jpg",            photoUrl: "default.jpg",            role: "",            status: "active",            carpenterProfile: "",            createdAt: null,            updatedAt: null,          ),        ));  final UpdateUserUseCase updateUserUseCase;  final UpdatePasswordUseCase updatePasswordUseCase;  final GetUserDataUseCase getUserDataUseCase;  final RefreshTokenUseCase refreshTokenUseCase;  Future<void> init() async {    final String token = await LocalStorageService.getValue(      LocalStorageKeys.token,      defaultValue: "",    );    if (token.isNotEmpty) {      await refreshToken();    }  }  Future<void> getUserData() async {    final response = await getUserDataUseCase.call();    response.fold(      (failure) async {        if (failure.errMessage.contains("Unauthorized")) {          await refreshToken();        }else{          emit(            state.copyWith(              errorUser: true,            ),          );        }      },      (data) {        emit(state.copyWith(userDataModel: data, errorUser: false));      },    );  }  Future<void> refreshToken() async {    final response = await refreshTokenUseCase.call();    response.fold(      (failure) async {        emit(          state.copyWith(            message: failure.errMessage,            errorUser: true,          ),        );        await kNavigationService.clearAndNavigateTo(AppRoutes.authentication);      },      (data) {        emit(state.copyWith(userDataModel: data, errorUser: false));      },    );  }  Future<void> updateUser(BuildContext context, UpdateUser updateUser) async {    emit(state.copyWith(loading: true));    final result = await updateUserUseCase.call(updateUser);    result.fold(      (l) {        emit(state.copyWith(            loading: false, success: false, error: l.errMessage));        showCustomSnackBar(context, l.errMessage, SnackBarType.error);      },      (r) async {        emit(state.copyWith(          loading: false,          success: true,        ));        await refreshToken();        showCustomSnackBar(context, "Update Succeed", SnackBarType.success);      },    );  }  Future<void> updatePassword(      BuildContext context, UpdatePassword updateUser) async {    emit(state.copyWith(loading: true));    final result = await updatePasswordUseCase.call(updateUser);    result.fold(      (l) {        emit(state.copyWith(            loading: false, success: false, error: l.errMessage));        showCustomSnackBar(context, l.errMessage, SnackBarType.error);      },      (r) {        showCustomSnackBar(context, "Update Succeed", SnackBarType.success);        kNavigationService.goBack();        emit(state.copyWith(          loading: false,          success: true,        ));      },    );  }  get loading => state.loading;}